<template>
 <div class="app-container">
  <el-alert title="采购确认不改变库存；实际到货请到收货作业。列表不展示价格，详情单独授权。" type="info" :closable="false" class="mb8"/>
  <el-form inline size="small" @submit.prevent="search"><el-form-item label="单号"><el-input v-model="query.purchaseNo" clearable placeholder="完整采购单号"/></el-form-item><el-form-item label="仓库" v-if="can('erp:warehouse:list')"><PurchasingReferenceSelect kind="warehouse" v-model="query.warehouseId" style="width:180px"/></el-form-item><el-form-item label="供应商" v-if="can('erp:supplier:list')"><PurchasingReferenceSelect kind="supplier" v-model="query.supplierId" style="width:180px"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:130px"><el-option v-for="(name,status) in purchaseStates" :key="status" :label="name" :value="status"/></el-select></el-form-item><el-form-item><el-checkbox v-model="query.awaitingReceipt" @change="search">只看尚待收货</el-checkbox></el-form-item><el-form-item><el-button @click="search">查询</el-button><el-button type="primary" v-if="can('erp:purchase:add')" :disabled="busy||opening||closing" @click="start">新建采购单</el-button></el-form-item></el-form>
  <el-alert v-if="listError" title="采购列表读取失败，请重试；并非零条数据。" type="error" :closable="false"/>
  <el-alert v-if="lastResult" :title="'操作成功：采购 #'+lastResult.purchaseId+' · '+purchaseStates[lastResult.status]+' · v'+lastResult.version" type="success" :closable="true" @close="lastResult=null"/>
  <el-table :data="rows" size="small" v-loading="loading"><el-table-column prop="purchaseNo" label="采购单号" min-width="230" show-overflow-tooltip/><el-table-column prop="supplierName" label="供应商" min-width="130"/><el-table-column prop="warehouseName" label="仓库" min-width="120"/><el-table-column label="状态" width="110"><template #default="{row}">{{purchaseStates[row.status]}}</template></el-table-column><el-table-column label="已收/采购" width="120"><template #default="{row}">{{row.receivedQuantity}} / {{row.orderedQuantity}}</template></el-table-column><el-table-column prop="version" label="版本" width="60"/><el-table-column label="操作" fixed="right" width="260"><template #default="{row}"><el-button link type="primary" v-if="can('erp:purchase:query')" :disabled="locked" @click="show(row,'detail')">详情</el-button><el-button link v-if="row.status==='DRAFT'&&canEdit" :disabled="locked" @click="show(row,'edit')">编辑</el-button><el-button link v-for="action in allowed(row)" :key="action" :disabled="locked" @click="act(row,action)">{{purchaseActions[action]}}</el-button><el-button link type="primary" v-if="['CONFIRMED','PARTIAL_RECEIVED'].includes(row.status)&&can('erp:purchase:receive')" @click="router.push({path:'/erp/purchaseReceive',query:{purchaseId:String(row.purchaseId)}})">收货</el-button></template></el-table-column></el-table>
  <pagination v-show="!listError&&total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/>
  <el-dialog v-model="open" :title="title" class="erp-dialog" width="min(1000px, calc(100vw - 24px))" :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy" :before-close="beforeClose" @close="closed" @closed="closing=false">
   <el-alert v-if="error" :title="error" type="warning" :closable="false" class="mb8"/>
   <template v-if="mode==='create'||mode==='edit'">
    <el-form label-width="85px" size="small" :disabled="busy||!!pending"><el-form-item label="供应商" required><PurchasingReferenceSelect kind="supplier" v-model="form.supplierId" :disabled="!!form.purchaseId||busy||!!pending" :seeds="supplierSeed"/></el-form-item><el-form-item label="到货仓库" required><PurchasingReferenceSelect kind="warehouse" v-model="form.warehouseId" :disabled="!!form.purchaseId||busy||!!pending" :seeds="warehouseSeed"/></el-form-item><el-form-item label="币种" required><el-input v-model="form.currency" maxlength="3" style="width:120px"/></el-form-item></el-form>
    <el-table :data="form.lines" size="small"><el-table-column label="商品SKU" min-width="240"><template #default="{row}"><PurchasingReferenceSelect v-model="row.skuId" :seeds="row.skuId?[row]:[]" :disabled="busy||!!pending"/></template></el-table-column><el-table-column label="数量" width="160"><template #default="{row}"><el-input-number v-model="row.quantity" :min="1" :max="1000000000" :precision="0" :disabled="busy||!!pending" style="width:140px"/></template></el-table-column><el-table-column label="单价（最多4位小数）" width="200"><template #default="{row}"><el-input v-model="row.unitPrice" :disabled="busy||!!pending" placeholder="字符串，如0或12.3456" maxlength="21"/></template></el-table-column><el-table-column label="行额预览" width="150"><template #default="{$index}">{{preview.amounts?.[$index]||'—'}}</template></el-table-column><el-table-column label="操作" width="60"><template #default="{$index}"><el-button link type="danger" :disabled="busy||!!pending" @click="form.lines.splice($index,1)">移除</el-button></template></el-table-column></el-table>
    <el-button size="small" :disabled="busy||!!pending||form.lines.length>=100" @click="form.lines.push({quantity:1,unitPrice:''})" class="mt8">添加商品行</el-button><p>总额预览：{{preview.total||'请完善商品、数量与价格'}}（服务端复核）</p><el-input v-model="form.remark" type="textarea" maxlength="500" placeholder="备注（不换行，最多500字）" :disabled="busy||!!pending"/>
   </template>
   <template v-else-if="mode==='detail'">
    <p>{{form.purchaseNo}} · {{purchaseStates[form.status]}} · v{{form.version}}</p><p>{{form.supplierName}} → {{form.warehouseName}} · {{form.currency}} {{form.orderedAmount}}</p><p v-if="form.closeReason">取消/关闭原因：{{form.closeReason}}</p><p v-if="form.remark">备注：{{form.remark}}</p>
    <el-table :data="form.lines" size="small"><el-table-column prop="skuCode" label="SKU" min-width="120"/><el-table-column prop="productName" label="商品快照" min-width="160"/><el-table-column prop="unit" label="单位" width="70"/><el-table-column prop="orderedQuantity" label="采购" width="85"/><el-table-column prop="receivedQuantity" label="已收" width="85"/><el-table-column label="未收/关闭余量" width="130"><template #default="{row}">{{row.orderedQuantity-row.receivedQuantity}}{{form.status==='CLOSED'?'（关闭）':''}}</template></el-table-column><el-table-column prop="unitPrice" label="单价" width="150"/><el-table-column prop="lineAmount" label="金额" width="150"/></el-table>
    <el-button v-if="can('erp:purchaseReceipt:list')" class="mt8" @click="router.push({path:'/erp/purchaseReceipt',query:{purchaseId:String(form.purchaseId)}})">查看收货记录</el-button><h4>操作记录</h4><el-alert v-if="eventsError" title="操作记录读取失败" type="error" :closable="false"/><el-table :data="events" size="small"><el-table-column prop="action" label="动作"/><el-table-column prop="toStatus" label="结果状态"/><el-table-column prop="toVersion" label="版本"/><el-table-column prop="createTime" label="时间" min-width="170"/></el-table><pagination v-show="eventsTotal>0" :total="eventsTotal" v-model:page="eventPage" :limit="10" @pagination="loadEvents"/>
   </template>
   <template v-else><p>{{form.purchaseNo}} · 当前v{{form.version}}</p><el-alert :title="mode==='confirm'?'确认后冻结报价及快照，尚不入库。':mode==='close'?'关闭未收余量，不回滚已收库存，也不会标记为付款。':'只能取消未收货采购单，取消后不可重新打开。'" type="warning" :closable="false"/><el-input v-if="mode!=='confirm'" class="mt8" v-model="form.reason" type="textarea" maxlength="500" placeholder="必填原因（不换行）" :disabled="busy||!!pending"/></template>
   <template #footer><el-button :disabled="busy" @click="closeDialog">{{mode==='detail'?'关闭':'关闭 / 放弃本次重试'}}</el-button><el-button v-if="mode!=='detail'" type="primary" :loading="busy" @click="submit">{{pending?'沿用原请求重试':mode==='create'||mode==='edit'?'保存草稿':purchaseActions[mode]}}</el-button></template>
  </el-dialog>
 </div>
</template>
<script setup name="PurchaseWorkspace">
import {ref,reactive,computed,watch,onBeforeUnmount,onDeactivated,onActivated} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {checkPermi} from '@/utils/permission'
import {listPurchases,getPurchase,purchaseEvents,addPurchase,editPurchase,actPurchase} from '@/api/erp/purchase'
import {purchaseStates,purchaseActions,purchasePayload,purchasePreview,immutablePayload,safeID} from '@/utils/purchasing.mjs'
import PurchasingReferenceSelect from './PurchasingReferenceSelect.vue'
const router=useRouter(),route=useRoute(),can=p=>checkPermi([p]),canEdit=computed(()=>can('erp:purchase:edit')&&can('erp:purchase:query'))
const rows=ref([]),total=ref(0),loading=ref(false),listError=ref(false),lastResult=ref(null),open=ref(false),closing=ref(false),opening=ref(false),busy=ref(false),mode=ref('detail'),form=ref({lines:[]}),pending=ref(null),error=ref(''),events=ref([]),eventsTotal=ref(0),eventsError=ref(false),eventPage=ref(1)
const query=reactive({pageNum:1,pageSize:10,purchaseNo:'',status:'',awaitingReceipt:false,warehouseId:undefined,supplierId:undefined}),locked=computed(()=>busy.value||opening.value||closing.value),title=computed(()=>({create:'新建采购单',edit:'编辑采购草稿',detail:'采购单详情 · 冻结快照'}[mode.value]||purchaseActions[mode.value])),preview=computed(()=>{try{return purchasePreview(form.value.lines||[])}catch{return{}}}),supplierSeed=computed(()=>form.value.supplierId?[{supplierId:form.value.supplierId,supplierName:form.value.supplierName}]:[]),warehouseSeed=computed(()=>form.value.warehouseId?[{warehouseId:form.value.warehouseId,warehouseName:form.value.warehouseName}]:[])
let listSeq=0,detailSeq=0,eventSeq=0,viewSeq=0,inactive=false
async function load(){if(inactive)return;const t=++listSeq;loading.value=true;listError.value=false;try{const r=await listPurchases({...query});if(t===listSeq){rows.value=r.rows;total.value=r.total}}catch{if(t===listSeq){rows.value=[];total.value=0;listError.value=true}}finally{if(t===listSeq)loading.value=false}}
function search(){query.pageNum=1;return load()}
function allowed(row){const actions=row.status==='DRAFT'?['confirm','cancel']:row.status==='CONFIRMED'?['cancel','close']:row.status==='PARTIAL_RECEIVED'?['close']:[];return actions.filter(a=>can('erp:purchase:'+a))}
function start(){if(inactive)return;if(locked.value||open.value||!can('erp:purchase:add'))return;mode.value='create';form.value={requestKey:crypto.randomUUID(),currency:'USD',remark:'',lines:[{quantity:1,unitPrice:''}]};pending.value=null;error.value='';open.value=true}
async function show(row,next){if(inactive)return;if(locked.value||open.value||!can('erp:purchase:query')||(next==='edit'&&!canEdit.value))return;const t=++detailSeq;opening.value=true;try{const r=await getPurchase(row.purchaseId);if(t!==detailSeq)return;mode.value=next;form.value={...r.data,requestKey:crypto.randomUUID(),lines:r.data.lines.map(l=>({...l,quantity:l.orderedQuantity}))};pending.value=null;error.value='';open.value=true;eventPage.value=1;if(next==='detail')loadEvents()}finally{if(t===detailSeq)opening.value=false}}
function act(row,next){if(inactive)return;if(locked.value||open.value||!allowed(row).includes(next))return;mode.value=next;form.value={purchaseId:row.purchaseId,purchaseNo:row.purchaseNo,version:row.version,reason:'',requestKey:crypto.randomUUID()};pending.value=null;error.value='';open.value=true}
async function loadEvents(){if(inactive)return;if(mode.value!=='detail'||!open.value)return;const t=++eventSeq;eventsError.value=false;try{const r=await purchaseEvents(form.value.purchaseId,{pageNum:eventPage.value,pageSize:10});if(t===eventSeq){events.value=r.rows;eventsTotal.value=r.total}}catch{if(t===eventSeq){events.value=[];eventsTotal.value=0;eventsError.value=true}}}
async function submit(){if(inactive)return;if(busy.value||!open.value||mode.value==='detail')return;const view=viewSeq;busy.value=true;error.value='';try{
 if(!pending.value){let payload;if(mode.value==='create'||mode.value==='edit')payload=purchasePayload(form.value);else{const reason=form.value.reason||'';if(mode.value!=='confirm'&&(!reason.trim()||reason!==reason.trim()||reason.length>500||/[\x00-\x1f\x7f]/.test(reason)))throw Error('原因须为不含换行/首尾空白的1—500字');payload={version:form.value.version,requestKey:form.value.requestKey,...(mode.value==='confirm'?{}:{reason})}};pending.value=immutablePayload({mode:mode.value,id:form.value.purchaseId,payload})}
 const p=pending.value;let r;if(p.mode==='create')r=await addPurchase(p.payload);else if(p.mode==='edit')r=await editPurchase(p.id,p.payload);else r=await actPurchase(p.id,p.mode,p.payload);if(inactive||view!==viewSeq)return;lastResult.value=r.data;closing.value=true;open.value=false;form.value={lines:[]};pending.value=null;ElMessage.success('采购操作已保存');await load()
 }catch(e){if(!inactive&&view===viewSeq)error.value=pending.value?'结果未确认，输入和版本已锁定；重试沿用原请求。关闭后先查单确认结果，不要直接重复新建。':(e.message||'请检查输入')}finally{if(view===viewSeq)busy.value=false}}
function closed(){if(open.value)return;closing.value=true;++detailSeq;++eventSeq;form.value={lines:[]};pending.value=null;error.value='';events.value=[];eventsTotal.value=0;opening.value=false}
function closeDialog(){if(busy.value)return;closing.value=true;open.value=false;closed()}
function beforeClose(done){if(busy.value)return;closeDialog();done()}
function clear(){busy.value=false;++viewSeq;++listSeq;++detailSeq;++eventSeq;open.value=false;form.value={lines:[]};pending.value=null;events.value=[];rows.value=[];total.value=0;opening.value=false;loading.value=false;lastResult.value=null}
function openLink(){if(inactive)return;const id=safeID(route.query.purchaseId);if(id&&can('erp:purchase:query'))return show({purchaseId:id},'detail')}
watch(()=>route.query.purchaseId,openLink)
onBeforeUnmount(()=>{inactive=true;clear()});onDeactivated(()=>{inactive=true;clear()});onActivated(()=>{if(inactive){inactive=false;closing.value=false;const pendingLoad=applyAwaitingLink()&&can('erp:purchase:list')?load():undefined;openLink();return pendingLoad}})
function applyAwaitingLink(){const raw=route.query.awaitingReceipt;if(raw!==undefined&&raw!=='true'&&raw!=='false'){++listSeq;rows.value=[];total.value=0;listError.value=true;return false}query.awaitingReceipt=raw==='true';query.pageNum=1;return true}
watch(()=>route.query.awaitingReceipt,()=>{if(!inactive&&applyAwaitingLink()&&can('erp:purchase:list'))load()})
if(applyAwaitingLink()&&can('erp:purchase:list'))load();openLink()
</script>
